import base64,hashlib,json,os,pathlib,sys,zlib
def canon(x): return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode('utf-8')
def sha(b): return hashlib.sha256(b).hexdigest()
def ident(b): return {'length':len(b),'sha256':sha(b)}
def dec(s): return base64.b64decode(s,validate=True)
def enc(b): return base64.b64encode(b).decode('ascii')
def emit(o,exit_code):
 raw=canon(o)
 if len(raw)>67108864: o={'reason':'TRANSPORT_BOUND_EXCEEDED','authority':False,'proposed_writes':[]};raw=canon(o);exit_code=23
 z=zlib.compressobj(9,zlib.DEFLATED,-15,8,zlib.Z_FIXED); packed=z.compress(raw)+z.flush()
 wire=canon({'schema':'p48-ab-frame-v1','raw_length':len(raw),'sha256':sha(raw),'codec':'deflate-raw-fixed','data':enc(packed),'end':'P48_AB_END'})+b'\n'
 if len(wire)>16384:
  print(json.dumps({'reason':'TRANSPORT_BOUND_EXCEEDED','authority':False,'proposed_writes':[]},separators=(',',':')));sys.exit(23)
 sys.stdout.buffer.write(wire);sys.stdout.buffer.flush();sys.exit(exit_code)
def refuse(reason): emit({'reason':reason,'authority':False,'proposed_writes':[]},23)
def decode_result(a):
 if not isinstance(a,dict) or not isinstance(a.get('result'),dict) or not isinstance(a.get('request'),dict):refuse('ACTUAL_A_UNAVAILABLE')
 r=a['result']
 if r.get('session_id') is not None or r.get('exit_code') is None:refuse('ACTUAL_A_NONTERMINAL')
 try:
  f=json.loads(r['output'])
  if f['schema']!='p48-ab-frame-v1' or f['end']!='P48_AB_END' or f['codec']!='deflate-raw-fixed':refuse('ACTUAL_A_OUTPUT_INVALID')
  b=zlib.decompress(dec(f['data']),-15)
  if ident(b)!={'length':f['raw_length'],'sha256':f['sha256']}:refuse('ACTUAL_A_OUTPUT_INVALID')
  return r,json.loads(b)
 except (KeyError,ValueError,TypeError,zlib.error):refuse('ACTUAL_A_OUTPUT_INVALID')
def fsync_parent(p):
 f=os.open(p.parent,os.O_RDONLY)
 try:os.fsync(f)
 finally:os.close(f)
def write(p,data,append=False):
 with p.open('ab' if append else 'xb') as f:f.write(data);f.flush();os.fsync(f.fileno())
 fsync_parent(p)
def run(q):
 mode=q['mode'];stage=q['stage'];op=q['operation']
 if mode not in ('readonly','durable') or stage not in ('A','B'):refuse('MODE_INVALID')
 p=dec(q['pre_a_prefix_b64']);current=dec(q['current_b64'])
 if ident(p)!=q['pre_a_identity']:refuse('PRIOR_IDENTITY_MISMATCH')
 if p and not p.endswith(b'\n'):refuse('INTERRUPTED_PREFIX_MISMATCH')
 try:rows=[json.loads(row) for row in p.splitlines()]
 except (ValueError,TypeError):refuse('INTERRUPTED_PREFIX_MISMATCH')
 if any(r.get('op_id')==op['op_id'] for r in rows):refuse('PREEXISTING_OPERATION')
 root=pathlib.Path(q['root']);journal=root/'copy-operations.jsonl';receipt=root/(op['op_id']+'-receipt.json')
 if root.is_absolute() or '..' in root.parts or root.parts[:2]!=('build','phase16-validation48-bootstrap'):refuse('DESTINATION_SCOPE_MISMATCH')
 if not op['op_id'] or any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_' for c in op['op_id']):refuse('OPERATION_NAME_INVALID')
 if any(parent.is_symlink() for parent in (root,*root.parents)):refuse('DESTINATION_SCOPE_MISMATCH')
 for w in op['writes']:
  path=pathlib.Path(w['path'])
  if path.is_absolute() or '..' in path.parts or root not in path.parents or any(parent.is_symlink() for parent in (path,*path.parents)):refuse('DESTINATION_SCOPE_MISMATCH')
 i=canon({'kind':'intent','op_id':op['op_id'],'sequence':len(rows)+1,'previous_row_sha256':sha(p.splitlines(keepends=True)[-1]) if p else None,'operation':op})+b'\n'
 ja=p+i;c=None;jb=None;rbytes=None
 if stage=='A':
  if current!=p:refuse('PRIOR_PREFIX_MISMATCH')
  writes=[{'path':str(journal),'kind':'append','data_b64':enc(i)}]+[{'path':w['path'],'kind':'exclusive','data_b64':w['data_b64']} for w in op['writes']]
 else:
  actual_a,ao=decode_result(q.get('actual_a'))
  if q['actual_a']['request']!=q.get('expected_a_request'):refuse('ACTUAL_A_REQUEST_MISMATCH')
  if actual_a['exit_code']!=op['expected_exit']:refuse('ACTUAL_A_EXIT_MISMATCH')
  if ao.get('op_id')!=op['op_id'] or ao.get('operation_sha256')!=sha(canon(op)):refuse('ACTUAL_A_BINDING_MISMATCH')
  if ao.get('reason')!=op['expected_reason']:refuse('ACTUAL_A_REASON_MISMATCH')
  if ao.get('mode')!=mode:refuse('ACTUAL_A_MODE_MISMATCH')
  if ao.get('post_a_identity')!=ident(ja):refuse('ACTUAL_A_JOURNAL_MISMATCH')
  if current!=ja:refuse('POST_A_JOURNAL_MISMATCH')
  if q.get('receipt_exists',False):refuse('RECEIPT_PREEXISTS')
  rbytes=canon({'schema':'p48-actual-A-receipt-v1','actual_a':q['actual_a'],'op_id':op['op_id'],'pre_a_identity':ident(p),'post_a_identity':ident(ja)})+b'\n'
  if q.get('expected_receipt_identity',ident(rbytes))!=ident(rbytes):refuse('RECEIPT_BINDING_MISMATCH')
  c=canon({'kind':'completion','op_id':op['op_id'],'sequence':len(rows)+2,'previous_row_sha256':sha(i),'intent_identity':ident(i),'receipt_identity':ident(rbytes),'post_a_identity':ident(ja)})+b'\n';jb=ja+c
  rr=[json.loads(row) for row in jb.splitlines()]
  if sum(r.get('op_id')==op['op_id'] and r.get('kind')=='intent' for r in rr)!=1 or sum(r.get('op_id')==op['op_id'] and r.get('kind')=='completion' for r in rr)!=1:refuse('OPERATION_COUNT_MISMATCH')
  writes=[{'path':str(receipt),'kind':'exclusive','data_b64':enc(rbytes)},{'path':str(journal),'kind':'append','data_b64':enc(c)}]
 if mode=='durable':
  if stage=='A':
   if not p:
    if root.exists():refuse('ROOT_PREEXISTS')
    os.mkdir(root,0o700);write(journal,i)
   else:
    if journal.read_bytes()!=p:refuse('PRIOR_PREFIX_MISMATCH')
    write(journal,i,True)
   for w in writes[1:]:
    dst=pathlib.Path(w['path']);data=dec(w['data_b64']);write(dst,data)
    if dst.read_bytes()!=data:refuse('DESTINATION_READBACK_MISMATCH')
   if journal.read_bytes()!=ja:refuse('INTENT_READBACK_MISMATCH')
  else:
   if journal.read_bytes()!=ja:refuse('POST_A_JOURNAL_MISMATCH')
   for w in op['writes']:
    if pathlib.Path(w['path']).read_bytes()!=dec(w['data_b64']):refuse('DESTINATION_READBACK_MISMATCH')
   write(receipt,rbytes)
   if receipt.read_bytes()!=rbytes:refuse('RECEIPT_READBACK_MISMATCH')
   write(journal,c,True)
   if journal.read_bytes()!=jb:refuse('COMPLETION_READBACK_MISMATCH')
 out={'schema':'p48-ab-result-v1','mode':mode,'stage':stage,'reason':op['expected_reason'] if stage=='A' else 'B_PREPARED','op_id':op['op_id'],'operation_sha256':sha(canon(op)),'authority':mode=='durable','runtime_admission':False,'pre_a_identity':ident(p),'post_a_identity':ident(ja),'post_b_identity':ident(jb) if jb is not None else None,'intent_b64':enc(i),'completion_b64':enc(c) if c is not None else None,'proposed_writes':writes}
 emit(out,op['expected_exit'] if stage=='A' else 0)
run(json.loads(dec(sys.argv[1])))

